$m = \Drupal::service('module_handler');
$active = array_keys($m->getModuleList());
sort($active);
echo 'active modules: ' . count($active) . PHP_EOL;
foreach (['openculturas_openstreetmap','openculturas_map','geocoder','openculturas_content','default_content','openculturas_media','openculturas_section','openculturas_faq','openculturas_discussions'] as $x) {
